function shell(content){return `<div class="a-app"><header class="a-header"><button class="a-brand" data-a="home" aria-label="Accueil KI Arena"><span>KI</span> ARENA <small>HORIZONS<br>ÉDITION / 20</small></button><nav aria-label="Navigation principale">${btn('Accueil','home','',page==='home'?'selected':'')}${btn('Solo','adventure','',page==='run'||page==='setup'?'selected':'')}${btn('Arcade','arcade','',page==='arcade'||page==='extra'||page==='mini'?'selected':'')}${btn('Collection','collection','',page==='collection'?'selected':'')}${btn('Multi','party','',page==='party'?'selected':'')}</nav><div class="a-header-tools">${run&&page==='run'?btn('⌘ <span>Carte</span>','map','aria-label="Carte complète" title="Carte complète · M"','icon'):''}${run&&page==='run'&&!['end'].includes(run.phase)?btn('✕ <span>Quitter</span>','retreat','aria-label="Quitter la run" title="Quitter la run"','icon'):''}${btn('♫ <span>Audio</span>','audio','aria-label="Musique et effets"','icon')}${btn('⚙','settings','aria-label="Paramètres et médias"','icon')}${btn('☰','navmore','aria-expanded="false" aria-label="Plus de commandes"','icon a-navmore')}</div></header>${saveError?`<aside class="a-save-error" role="alert">${esc(saveError)} ${run?btn('Exporter la run','export'):''}</aside>`:''}<main class="a-main">${content}</main><footer class="a-footer"><span>KI ARENA · Fan game local</span><span>4 mondes · ${page==='run'?esc(run.seed):'Aucune connexion requise'}</span>${btn('Modes historiques ↗','legacy','','text')}</footer>${page==='run'&&run&&!['draft','end'].includes(run.phase)?bottomBar():''}${modal?modalView():''}</div>`;}
