function draft(){if(['16.0.0','17.0.0','19.0.0','20.0.0'].includes(run.rulesVersion))return mixedDraftMarkup({run,c:cat(),hud:runHud(),fighter,gearCard,esc,btn,selectedOffer});const c=cat(),hero=run.step<5;return `${runHud()}<section class="a-draft-heading"><span class="a-eyebrow">LE RECRUTEMENT · ${hero?'TON ÉQUIPE':'TES ARMES'}</span><h1>${hero?'Un allié. Un destin.':'De quoi changer le combat.'}</h1><p>Deux propositions se dévoilent. La dernière garde son secret.</p><div class="a-progress">${Array.from({length:8},(_,i)=>`<i class="${i<=run.step?'active':''}"></i>`).join('')}</div></section><div class="a-offers v14-draft-offers">${run.offers.map((o,i)=>{const id=typeof o==='string'?o:o.id,token=o.token||id,mystery=o.band==='mystery'&&!o.revealed;if(o.disabled)return `<div class="v14-draft-offer unavailable"><b>Proposition indisponible</b><p>${esc(o.reason)}</p><button disabled class="a-button" data-a="draft" data-id="${esc(token)}" data-offer-index="${i}">Incompatible</button></div>`;if(mystery)return `<button class="v14-draft-offer a-mystery" data-a="draft" data-id="${esc(token)}" data-offer-index="${i}" aria-label="Choisir la proposition mystère"><div class="v14-mystery-orbit"><span>?</span></div><small>UN DESTIN INCONNU</small><h2>Le choix du mystère</h2><p>Il attend ta décision pour se révéler.</p><strong>Choisir le mystère →</strong></button>`;const h=hero?c.byId.get(id):c.byItem.get(id);return `<div class="v14-draft-offer">${hero?fighter(h):gearCard(h)}${hero?`<div class="v14-offer-label"><b>${esc(h.name)}</b><span>${esc(h.form)}</span><small class="v14-ability-preview">${esc(h.effects.slice(0,2).map(e=>e.name).join(' · ')||'Un combattant à découvrir')}</small></div>`:''}${btn(hero?'Recruter →':'Emporter →','draft',`data-id="${esc(token)}" data-offer-index="${i}"`,'primary')}</div>`;}).join('')}</div><div class="a-draft-roster"><b>TON ÉQUIPE</b>${run.units.map(u=>`<span>${esc(c.byId.get(u.cardId).name)}</span>`).join('')}<small>Touches 1 · 2 · 3 pour choisir</small></div>`;}

function mapSvg(global=false){const allowed=availableNodes(run),current=run.nodes.find(n=>n.id===run.current),focus=current?.row??-1,limit=run.legacyMap?14:BOSS_ROW,from=global?0:Math.max(0,Math.min(limit-4,focus-1)),to=global?limit:Math.min(limit,from+5),height=(to-from+1)*64+64,point=n=>mapPoint(n,from,to,run.act);let lines='';for(const n of run.nodes.filter(n=>n.row>=from&&n.row<=to))for(const id of n.next){const t=run.nodes.find(x=>x.id===id);if(t.row<from||t.row>to)continue;const a=point(n),b=point(t);lines+=`<path data-from="${n.id}" data-to="${t.id}" class="${run.trail.includes(n.id)&&run.trail.includes(t.id)?'taken':n.id===run.current&&allowed.includes(t.id)?'possible':''}" d="M${a.x},${a.y} C${a.x},${a.y-33} ${b.x},${b.y+33} ${b.x},${b.y}"/>`;}
 return `<svg class="a-map-svg ${global?'global':''}" viewBox="0 0 360 ${height}" aria-label="Chemins de l’acte ${run.act+1}" role="group"><g class="a-routes">${lines}</g>${run.nodes.filter(n=>n.row>=from&&n.row<=to).map(n=>{const p=point(n),reachable=allowed.includes(n.id),done=run.trail.includes(n.id),info=n.kind==='event'?['Rencontre inconnue','?']:NODE_INFO[n.kind];return `<g class="a-node ${reachable?'reachable':''} ${done?'visited':''} ${n.id===run.current?'current':''} ${n.kind==='boss'?'boss':''}" transform="translate(${p.x} ${p.y})" ${reachable?`data-a="node" data-id="${n.id}" tabindex="0" role="button"`:''} aria-label="Étape ${n.row+1} · ${info[0]}${reachable?' · accessible':done?' · parcouru':' · à venir'}"><title>Étape ${n.row+1} · ${info[0]}</title><circle class="a-node-target" r="31"/><circle r="20"/><image href="${asset('assets/v14/icons/'+(done?'map':NODE_ICONS[n.kind])+'.svg')}" x="-12" y="-12" width="24" height="24"/>${n.id===run.current?'<path class="a-player-marker" d="M-7,-36 L7,-36 L0,-26 Z"/>':''}${n.kind==='boss'?'<text class="a-boss-label" y="-30" text-anchor="middle">BOSS</text>':''}</g>`;}).join('')}</svg>`;}
function mapScreen(){const choices=run.nodes.filter(n=>availableNodes(run).includes(n.id)),bio=actTheme(run.act),row=run.nodes.find(n=>n.id===run.current)?.row??-1;return `${runHud()}<section class="a-map-scene v14-map ${bio.style}" data-act-theme="${bio.id}" style="--scene:url('${asset(bio.background)}');--chapter:${bio.color}"><div class="a-map-intro"><span class="a-eyebrow">CHAPITRE ${run.act+1} · ${esc(bio.sky)}</span><h1>${esc(bio.name)}</h1><p>${esc(bio.line)}</p><span class="a-map-step">${Math.max(0,row+1)} <small>/ ${run.legacyMap?15:10} ÉTAPES</small></span><span class="v14-route-promise">Le boss t’attend au bout de chaque route.</span></div><div class="a-map-local">${mapSvg()}<span class="a-map-hint">Suis une route éclairée</span></div><div class="a-route-choices">${choices.map((n,i)=>`<button class="a-route-card ${n.kind==='boss'?'boss':''} ${n.eventRare?'v19-rare-route':''}" data-a="node" data-id="${n.id}" data-kind="${n.kind}" style="--i:${i};--route-art:url('${asset(({rest:'assets/v9/rest.webp',event:'assets/v9/event.webp',shop:'assets/v9/merchant.webp',treasure:'assets/v9/treasure.webp',elite:'assets/v11/arena-ruins.webp',boss:'assets/v11/arena-sky.webp',normal:'assets/v11/'+bio.art+'.webp'})[n.kind]||bio.background)}')">${nodeIcon(n.kind)}<div><small>${['À GAUCHE','AU CENTRE','À DROITE'][n.lane]}</small><b>${n.kind==='event'?(n.eventRare?'Rencontre rare':'Rencontre inconnue'):NODE_INFO[n.kind][0]}</b><em>${n.kind==='boss'?'Le gardien du chapitre':n.kind==='elite'?'Une opposition redoutable':n.kind==='event'?(n.eventRare?'Une anomalie éclaire la route':'Une décision imprévisible'):n.kind==='normal'?'Des adversaires sur la route':n.kind==='rest'?'Souffler ou s’entraîner':n.kind==='shop'?'Préparer la suite':'Un seul trésor à emporter'}</em></div><i>→</i></button>`).join('')}</div></section>`;}

function prepare(){const e=run.pending,c=cat(),leader=[...e.enemies].sort((a,b)=>b.rank-a.rank)[0],boss=c.byId.get(leader.cardId);return `${runHud()}${e.kind==='boss'?`<div class="a-boss-banner"><span>♛</span><div><small>BOSS DE L’ACTE ${run.act+1}</small><h2>${esc(boss.name)}</h2><p>${esc(boss.effects[0]?.name||'Combat au sommet')} · ${esc(boss.form)}</p></div></div>`:''}<div class="a-combat-heading"><div><span class="a-eyebrow">${e.kind==='boss'?'RENCONTRE DE BOSS':e.kind==='elite'?'COMBAT ÉLITE':'COMBAT'} · ${esc(actTheme(run.act).name)}</span><h1>${e.kind==='boss'?'Prépare le défi.':'Prêt pour l’affrontement ?'}</h1><p>Équipe tes combattants, glisse les cartes sur le terrain si tu veux, puis lance le combat automatique. Limite : 30 rounds, départage aux PV restants.</p></div><div class="a-actions">${btn('Équipe & équipement','inventory','','light')}${btn('Lancer le combat →','fight','','primary')}${btn('Clore l’expédition','retreat','','text')}</div></div><section class="a-prebattle v192-prebattle"><div class="v192-pre-side ally"><div class="a-side-label"><b>TON ÉQUIPE</b><span>Armes visibles sur les cartes · glisser = cosmétique.</span></div><div class="a-fighters a-fighters-slide">${run.units.slice(0,5).map(u=>fighter(c.byId.get(u.cardId),{unit:u,small:true})).join('')}</div></div><div class="a-versus-divider"><span>VS</span></div><div class="v192-pre-side rival"><div class="a-side-label"><b>ADVERSAIRES</b><span>${e.enemies.length} adversaires${e.items.length?' · Équipement repéré':''}</span></div><div class="a-fighters">${e.enemies.map(u=>fighter(c.byId.get(u.cardId),{small:true,combatUnit:u})).join('')}</div></div></section><details class="a-details v14-diagnostics" ${globalThis.KI_DEVELOPER?'':'hidden'}><summary>Diagnostic développeur</summary><p>Budget = arrondi(N / 4 × (vague + ${e.kind==='boss'?2:e.kind==='elite'?1:0})). Rangs : ${e.ranks.join(' + ')} = ${e.budget}. ${e.items.length} équipement(s), rareté max ${e.tier}/5. Après la vague 20, le budget continue de croître.</p><p>${e.enemies.map(u=>esc(c.byId.get(u.cardId).name)+': '+(gearFor(run,u,true).map(g=>esc(g.name)).join(', ')||'sans équipement')).join(' · ')}</p></details>`;}
function battleContents(ev){const c=cat(),units=ev.units,side=team=>`<div class="a-combat-team ${team==='A'?'player':'enemy'}" aria-label="${team==='A'?'Ton équipe':'Adversaires'}">${units.filter(f=>f.team===team).map(f=>fighter(c.byId.get(f.cardId),{small:true,combatUnit:f})).join('')}</div>`;return side('A')+'<div class="v193-center-seal" aria-hidden="true"><span>KI</span><small>ARENA</small></div>'+side('B');}
function initiative(ev){return ev.units.filter(u=>u.alive).sort((a,b)=>b.speed-a.speed||a.uid.localeCompare(b.uid)).map(u=>`<span class="${u.uid===ev.actor?'acting':''} ${u.team==='A'?'ally':'rival'}" data-initiative="${esc(u.uid)}"><b>${esc(u.name)}</b><small>${u.speed} VIT</small></span>`).join('');}

function cueMarkup(e){const ctx=visualContext(e),who=e.units?.find(u=>u.uid===(e.type==='ko'?e.target:e.actor))?.name||'Le duel commence';return '<b>'+esc(who)+'</b><span>'+esc(ctx.technique||attackProfile(e,ctx).label||'Chaque décision compte')+'</span>';}
function fightScreen(){const result=run.combat.result,ev=viewEvent||result.events[Math.max(0,run.combat.cursor-1)]||result.events[0];return `${runHud()}<div class="a-combat-heading"><div><span class="a-eyebrow a-battle-round">${run.pending.kind==='boss'?'♛ BOSS / ':'AUTO COMBAT / '}ROUND ${ev.round||1}</span><h1>Le choc des mondes.</h1></div><div class="a-actions">${btn(paused?'▶ Reprendre':'Ⅱ Pause','pause','','light')}${btn('Vitesse ×'+speed,'speed','','light')}${btn('Passer →','skip','','text')}</div></div><section class="a-battlefield v192-arena v193-stage" data-theme="${esc(run.worlds[0])}" style="--scene:url('${asset('assets/v11/'+biomeFor(run.act,run.pending.kind).art+'.webp')}')"><div class="v193-stage-top"><span class="v193-side-title">TON ÉQUIPE</span><div class="v193-action-cue">${cueMarkup(ev)}</div><span class="v193-side-title enemy">ADVERSAIRES</span></div><div class="a-battle-units">${battleContents(ev)}</div><div class="v193-stage-bottom"><span class="a-round-token">${ev.round||1}</span><div class="a-event-message" aria-live="polite">${esc(ev.message)}</div></div></section><div class="v193-initiative"><small>INITIATIVE · VIT</small><div>${initiative(ev)}</div></div><div class="a-battle-log"><span class="a-battle-progress">AUTOMATIQUE · ${Math.round(run.combat.cursor/result.events.length*100)}%</span><details><summary>Journal de combat</summary><ol>${result.events.slice(0,run.combat.cursor).slice(-30).map(e=>`<li>${esc(e.message)}</li>`).join('')}</ol></details></div>`;}
function encounterScene(){const phase=run.phase,path=phase==='reward'?'treasure':phase==='event'?'event':phase==='rest'?'rest':phase==='shop'?'merchant':'sky';let content='';
 if(phase==='reward')content=`<span class="a-eyebrow">${run.pending?.kind==='boss'?'BOSS VAINCU · ':'RENCONTRE TERMINÉE · '}CHOISIS 1 RÉCOMPENSE</span><h1>La route continue.</h1><p>${run.pending?'+25% de PV aux survivants. L’expérience revient aux combattants joués et survivants.':'Un seul bonus à emporter. Le coffre ne soigne pas automatiquement.'}</p><div class="a-rewards">${run.rewards.map((rw,i)=>`<button class="a-reward" data-a="reward" data-index="${i}"><span>${({coins:'◉',heal:'✚',item:'⚔',recruit:'♟',passive:'✧',training:'⚔',vigor:'⬡'})[rw.type]}</span><h2>${esc(rw.title)}</h2><p>${esc(rw.text)}</p>${rw.type==='item'?`<small>${esc(effectDescription(cat().byItem.get(rw.id)))}</small>`:''}<b>CHOISIR →</b></button>`).join('')}</div>`;
 if(phase==='rest')content=`<span class="a-eyebrow">HALTE / À TOI DE CHOISIR</span><h1>Un instant de répit.</h1><p>Soigner l’équipe ou préparer la prochaine bataille.</p><div class="a-rewards"><button class="a-reward" data-a="rest" data-id="heal"><span>☀</span><h2>Se reposer</h2><p>+50% de PV max aux vivants.</p><b>CHOISIR →</b></button><button class="a-reward" data-a="rest" data-id="train"><span>⚔</span><h2>S’entraîner</h2><p>+3% ATQ pour cette run.</p><b>CHOISIR →</b></button></div>`;
 if(phase==='event'){content=eventMarkup(run.activeEvent,{mobile:matchMedia('(max-width:720px)').matches,run,selected:selectedEvent});}
 if(phase==='shop')content=`<span class="a-eyebrow">MARCHAND / ${run.coins} ZÉNIS</span><h1>Le bon équipement.</h1><p>Achats uniques pour cette visite, objets compatibles avec l’équipe.</p><div class="a-rewards">${run.shop.map((o,i)=>`<article class="a-reward">${gearCard(cat().byItem.get(o.id))}${btn(o.bought?'Acheté':o.price+' zénis','buy',`data-index="${i}" ${o.bought||run.coins<o.price?'disabled':''}`,'primary')}</article>`).join('')}</div><div class="a-actions">${btn('Soin équipe · 30 zénis','care',run.careBought||run.coins<30||!run.units.some(u=>u.hp<u.maxHp)?'disabled':'','light')}${btn('Continuer →','leave','','primary')}</div>`;
 if(phase==='result')content=`<span class="a-eyebrow">COMBAT TERMINÉ</span><h1>Rassemble tes forces.</h1><p>${esc(run.resultText)}</p>${btn('Continuer →','leave','','primary')}`;
 if(phase==='end')content=`<span class="a-eyebrow">FIN DE RUN</span><h1>Jusqu’au dernier.</h1><p>${run.history.filter(h=>h.win).length} victoires · acte ${run.act+1} · ${run.dead.length} combattants perdus</p><p>Seed : ${esc(run.seed)}</p><div class="a-actions">${btn('Rejouer cette seed','replay','','primary')}${btn('Nouvelle aventure','setup','','light')}${btn('Exporter le bilan','export','','text')}</div>`;
 return `${runHud()}<section class="a-encounter-scene" style="--scene:url('${asset('assets/v9/'+path+'.webp')}')"><div class="a-encounter-copy">${content}</div></section>`;}
function runScreen(){return run.phase==='draft'?draft():run.phase==='map'?mapScreen():run.phase==='prepare'?prepare():run.phase==='combat'?fightScreen():encounterScene();}
function bottomBar(){const c=cat();return `<aside class="a-bottom-bar v14-team-rail"><button data-a="inventory" class="v14-rail-team" aria-label="Ouvrir l’équipe et le sac">${run.units.slice(0,5).map(u=>`<span class="v14-rail-hero" title="${esc(c.byId.get(u.cardId).name)}">${faceThumb(c.byId.get(u.cardId))}<span class="v14-rail-hp"><i style="width:${liveUnit(u)?liveUnit(u).hp/liveUnit(u).maxHp*100:u.hp/u.maxHp*100}%"></i></span><small>${u.weapon?'⚔':''}${u.armor?'⬡':''}</small></span>`).join('')}</button><button class="a-button primary v14-bag-button" data-a="inventory">${nodeIcon('inventory')}<span>Sac <b>${run.items.length}</b></span></button></aside>`;}

function inventory(){return inventoryMarkup({run,selectedItem,filter:inventoryFilter,selectedReserve,cardMarkup:inventoryCard,gearCard});}

function audioPanel(){return `<div class="a-modal-title"><h2>Audio</h2>${btn('Fermer ×','close','','light')}</div><p>Musique : 5% au départ. Bruitages de combat et musique se règlent séparément.</p><div class="a-audio-controls">${btn(audioSettings.muted?'Réactiver le son':'Couper le son','mute','','primary')}${['music','sfx'].map(k=>`<label>${k==='music'?'Musique':'Effets'} <output>${Math.round(audioSettings[k]*100)}%</output><input type="range" data-volume="${k}" min="0" max="1" step=".01" value="${audioSettings[k]}"></label>`).join('')}<label>Bande-son locale<select id="a-music-world"><option value="ALL" ${audioSettings.track==='ALL'?'selected':''}>Tous les univers</option>${WORLDS.map(w=>`<option value="${w}" ${audioSettings.track===w?'selected':''}>${worldName(w)}</option>`).join('')}</select></label><label class="a-file-label">Importer une musique de ton PC<input id="a-music-file" type="file" accept="audio/*"></label><p class="a-help">Les bandes originales des œuvres ne sont pas fournies dans les sources. Utilise tes fichiers locaux ; ils restent sur cet appareil. Sans import, la musique reste silencieuse.</p><div class="a-actions">${btn('▶ Écouter','musicplay','','light')}${btn('■ Arrêter','musicstop','','text')}</div><span id="a-music-status" role="status"></span></div>`;}
function settingsPanel(){return `<button class="a-button light" data-guide="restart">Revoir le guide de première partie</button><button class="a-button light" data-a="fx-lab">Galerie des animations</button><button class="a-button light" data-a="legacy">Modes historiques</button><div class="v19-creator-entry">${btn('Accès créateur','creator','','light')}</div><div class="a-modal-title"><h2>Médias & sauvegardes</h2>${btn('Fermer ×','close','','light')}</div><section class="a-panel"><h3>Importer les portraits Card Studio</h3><p>Choisis le manga puis le dossier de portraits. Noms attendus : ID de carte, ID_arena, ID_normal ou ID_special (.webp, .png, .jpg). Chaque finition est conservée séparément. Les fichiers restent locaux.</p><select id="a-portrait-world">${WORLDS.map(w=>`<option value="${w}">${worldName(w)}</option>`).join('')}</select><label class="a-file-label">Choisir le dossier de portraits<input type="file" id="a-portraits" webkitdirectory multiple></label><p class="a-help">Les 600 SVG DB fournis sont inclus. Les portraits HXH/Naruto/One Piece ne sont pas dans le ZIP source. Les portraits absents sont signalés sans image inventée.</p><span id="a-portrait-status" role="status"></span></section><section class="a-panel"><h3>Ta run</h3><p>Les sauvegardes historiques restent séparées. Exporter permet de déplacer ta run vers un autre navigateur.</p>${run?btn('Exporter la run','export','','light'):''}<label class="a-file-label">Importer une run Arène<input type="file" id="a-import-run" accept=".json"></label></section>`;}
function inspectPanel(){
  const catLive=run?runCatalog(run):registry(mini?.worlds||WORLDS,mini?.statsMode);
  const full=registry(WORLDS);
  let h=catLive.byId.get(inspected)||full.byId.get(inspected)||catLive.byItem?.get(inspected)||full.byItem?.get(inspected);
  const isGear=!!(h&&h.category&&!h.form);
  const own=!isGear&&page==='run'?run?.units.find(u=>u.cardId===inspected):null;if(h&&own)h={...h,...battleCard(run,own)};
  if(!h)return `<div class="a-inspect-viewer v20-inspect"><button class="v20-inspect-x" data-a="close" aria-label="Fermer">×</button><p>Carte introuvable.</p></div>`;
  const seed=inspectedSeed||run?.seed||mini?.seed||globalThis.KI_PARTY_DEBUG?.getState?.()?.seed||'ARENA';
  const edition=inspectedFinish||own?.edition||editionFor(seed,h.id);
  const gearDesc=isGear?effectDescription(h):'';
  const techs=isGear
    ?`<li class="v20-tech" style="--i:0"><b>${esc(h.name||'Objet')}</b><span>${esc(gearDesc||'Effet de jeu')}</span></li>`
    :(h.effects||[]).map((e,i)=>{
      const desc=e.description||'';
      return `<li class="v20-tech" style="--i:${i}"><b>${esc(e.name)}</b>${desc?`<span>${esc(desc)}</span>`:''}</li>`;
    }).join('')||'<li class="v20-tech"><b>Aucune capacité listée</b></li>';
  const draftPick=page==='run'&&run?.phase==='draft'&&selectedOffer&&run.offers.find(o=>o.token===selectedOffer&&o.id===h.id);
  const rewardIdx=(page==='run'&&run?.phase==='reward'&&run.rewards)?run.rewards.findIndex(rw=>(rw.type==='recruit'||rw.type==='item')&&rw.id===h.id):-1;
  const rewardPick=rewardIdx>=0?run.rewards[rewardIdx]:null;
  const shopIdx=(page==='run'&&run?.phase==='shop'&&run.shop)?run.shop.findIndex(o=>o.id===h.id):-1;
  const shopPick=shopIdx>=0?run.shop[shopIdx]:null;
  const ctaHtml=draftPick
    ?btn(draftPick.kind==='hero'?'Recruter →':'Emporter →','draft',`data-id="${esc(draftPick.token)}"`,'primary v20-draft-pick is-shown')
    :rewardPick
      ?btn(rewardPick.type==='recruit'?'Recruter →':'Emporter →','reward',`data-index="${rewardIdx}"`,'primary v20-draft-pick is-shown')
      :shopPick
        ?btn(shopPick.bought?'Déjà acheté':`Acheter · ${shopPick.price} zénis →`,'buy',`data-index="${shopIdx}" ${shopPick.bought||run.coins<shopPick.price?'disabled':''}`,'primary v20-draft-pick is-shown')
        :'';
  return `<div class="a-inspect-viewer v20-inspect">
    <button class="v20-inspect-x" data-a="close" aria-label="Fermer">×</button>
    <div class="a-inspect-layout v20-inspect-layout">
      <figure class="a-inspect-card" data-card-id="${esc(h.id)}">${cardMarkup(isGear?{...h,effects:[{name:gearDesc,description:gearDesc}]}:{...h},{seed,edition,equipment:isGear})}</figure>
      <div class="a-inspect-copy v20-inspect-copy">
        <ul class="a-inspect-techs">${techs}</ul>
        ${ctaHtml}
      </div>
    </div>
  </div>`;
}

function modalView(){return `<div class="a-overlay" data-a="backdrop"><section class="a-modal ${modal==='inventory'?'drawer':modal==='map'?'map-modal':modal==='fx'?'fx-lab-modal':'compact'}" role="dialog" aria-modal="true" aria-label="${modal==='map'?'Carte complète':modal==='inventory'?'Inventaire':modal==='audio'?'Audio':modal==='inspect'?'Détails du combattant':modal==='creator'?'Atelier créateur':'Paramètres'}" tabindex="-1">${modal==='fx'?labMarkup():modal==='inventory'?inventory():modal==='map'?`<div class="a-modal-title"><div><span class="a-eyebrow">ACTE ${run.act+1}</span><h2>La route vers le boss.</h2></div>${btn('Fermer ×','close','','light')}</div><p>Orange : parcouru · vert : accessible · les grandes cartes de route restent les cibles de sélection.</p><div class="a-global-map" style="--map-art:url('${asset(actTheme(run.act).background)}')">${mapSvg(true)}</div>`:modal==='audio'?audioPanel():modal==='inspect'?inspectPanel():modal==='retreat'?`<div class="a-modal-title"><h2>La route s’arrête ici ?</h2></div><p>Cette expédition sera terminée. Son équipe et ses contributions resteront dans tes souvenirs.</p><div class="a-actions">${btn('Terminer et conserver le bilan','confirm-retreat','','primary')}${btn('Continuer l’aventure','close','','light')}</div>`:modal==='creator'?creatorPanel():settingsPanel()}</section></div>`;}
function collection(){return collectionView(fighter);}
function startMini(mode){mini=createMini(worlds,mode,document.querySelector('#v14-arcade-seed')?.value||undefined,preferredStats());page='mini';paused=false;render();window.scrollTo(0,0);}

function nextMini(){advanceMini(mini);}

function unusedOldCardPrice(c){return 8+Math.round(c.percentile*22);}

function miniOffers(){fillMiniOffers(mini);}

