function miniScreen(){const c=registry(mini.worlds,mini.statsMode);if(mini.done){let rankScore=0;if(mini.mode==='rank')for(let a=0;a<5;a++)for(let b=a+1;b<5;b++)if(c.byId.get(mini.rankSlots[a])[mini.statsMode==='raw'?'total':'percentile']>=c.byId.get(mini.rankSlots[b])[mini.statsMode==='raw'?'total':'percentile'])rankScore++;return `<section class="a-mini-result"><span class="a-eyebrow">CHALLENGE TERMINÉ</span><h1>${mini.mode==='rank'?rankScore+'/10':mini.mode==='duel'?mini.score+'/10':mini.lastResult==='draw'?'ÉGALITÉ':mini.won?'VICTOIRE':'FIN DU DÉFI'}</h1><p>${mini.mode==='rank'?'Paires correctement ordonnées':mini.mode==='duel'?(mini.statsMode==='raw'?'Bonnes réponses · statistiques originales':'Bonnes réponses · puissance harmonisée'):mini.mode==='tournament'?'Arena Cup · '+(mini.round-1)+' manche(s) remportée(s)':'Ton équipe a affronté le rival en combat automatique.'}</p>${mini.mode==='rank'?`<ol class="a-rank-results">${mini.rankSlots.map((id,i)=>`<li><b>${i+1}.</b> ${esc(c.byId.get(id).name)} <span>${esc(c.byId.get(id).form)}</span></li>`).join('')}</ol>`:''}<div class="a-actions">${btn('Rejouer','mini',`data-id="${mini.mode}"`,'primary')}${btn('Arcade','arcade','','light')}${btn('Copier le résultat','copyresult','','text')}</div></section>`;}
 if(mini.mode==='duel')return `<section class="a-mini-heading"><span class="a-eyebrow">POWER DUEL / ${mini.round} SUR 10</span><div><h1>Qui domine son univers ?</h1><span class="a-lives">${'♥'.repeat(mini.lives)} <small>Combo ×${mini.combo}</small></span></div><p>Compare leur place dans leur manga. Les univers partagent la même échelle.</p></section><div class="a-duel-choices ${mini.answer?'revealed':''}">${mini.choices.map((id,i)=>`<button class="a-duel-choice ${mini.answer&&mini.answer.index===i?(mini.answer.correct?'correct':'wrong'):''}" data-a="duel" data-index="${i}" ${mini.answer?'disabled':''}>${fighter(c.byId.get(id))}<div class="a-duel-reveal">${mini.answer?(c.byId.get(id).percentile>=c.byId.get(mini.choices[1-i]).percentile?'Position supérieure':'Position inférieure'):'CHOISIR →'}</div></button>`).join('')}</div><div class="a-mini-feedback" role="status">${mini.answer?`<b>${mini.answer.correct?'Bien vu !':'Cette fois, l’autre dominait davantage son univers.'}</b>${btn(mini.round===10||mini.lives<=0?'Voir le résultat →':'Duel suivant →','miniNext','','primary')}`:'Touches 1 et 2 pour choisir'}</div>`;
 if(mini.mode==='rank')return `<section class="a-mini-heading"><span class="a-eyebrow">BLIND RANK / ${mini.round+1} SUR 5</span><h1>À quelle place ?</h1><p>1 = le plus puissant. Une fois placée, une carte ne bouge plus.</p></section><div class="a-rank-game">${fighter(c.byId.get(mini.queue[mini.round]))}<div class="a-rank-slots">${mini.rankSlots.map((id,i)=>`<button data-a="rank" data-index="${i}" ${id?'disabled':''}><b>${i+1}</b><span>${id?esc(c.byId.get(id).name):'Placer ici'}</span><i>${id?'✓':'+'}</i></button>`).join('')}</div></div>`;
 if(mini.replay)return miniReplay();if(mini.mode==='auto5')return quickTeam();
 if(mini.mode==='draft')return `<section class="a-mini-heading"><span class="a-eyebrow">DRAFT BUDGET SOLO / ${mini.team.length} SUR 5</span><h1>Fais les bons comptes.</h1><p><b>${mini.budget} zénis restants.</b> Trois choix, un seul recrutement. Garde de quoi remplir les cinq places.</p></section>${mini.team.length<5?`<div class="a-offers">${mini.offers.map(id=>`<div class="v14-solo-offer">${fighter(c.byId.get(id))}<b>${esc(c.byId.get(id).name)}</b><span>${esc(c.byId.get(id).form)}</span>${btn('Recruter · '+cardPrice(c.byId.get(id))+' zénis','miniDraft',`data-id="${esc(id)}"`,'primary')}</div>`).join('')}</div>`:`<div class="a-fighters">${mini.team.map(id=>fighter(c.byId.get(id),{small:true})).join('')}</div><div class="a-actions">${btn('Affronter le rival →','miniFight','','primary')}</div>`}<div class="a-draft-roster">${mini.team.map(id=>`<span>${esc(c.byId.get(id).name)}</span>`).join('')}</div>`;
 return `<section class="a-mini-heading"><span class="a-eyebrow">ARENA CUP / MANCHE ${mini.round} SUR 3</span><h1>Le tournoi t’attend.</h1><p>Ton équipe reste la même, les adversaires progressent. Aucun vainqueur révélé avant le match.</p></section><div class="a-fighters">${mini.team.map(id=>fighter(c.byId.get(id),{small:true})).join('')}</div><div class="a-actions">${btn('Jouer le match →','miniFight','','primary')}${mini.round===1?btn('Autre équipe','mini','data-id="tournament"','light'):''}</div>`;}
function quickTeam(){const c=registry(mini.worlds,mini.statsMode),pool=c.heroes.filter(h=>(h.name+' '+h.form).toLowerCase().includes(mini.query.toLowerCase())),selected=mini.team.map(id=>c.byId.get(id));return `<section class="a-mini-heading"><span class="a-eyebrow">AUTO 5 / TON ÉQUIPE</span><h1>Choisis tes cinq.</h1><p>Cliquer ajoute ou retire une carte. Une identité par équipe. Rival de même palier.</p></section><div class="a-quick-team"><div>${Array.from({length:5},(_,i)=>`<span>${selected[i]?esc(selected[i].name):'Place '+(i+1)}</span>`).join('')}</div>${btn('Lancer le combat →','miniFight',mini.team.length!==5?'disabled':'','primary')}</div><form id="a-auto-search" class="a-auto-search"><input id="a-auto-query" value="${esc(mini.query)}" placeholder="Nom ou forme…" aria-label="Rechercher un combattant"><button class="a-button light">Chercher</button></form><div class="a-collection-grid a-quick-grid">${pool.slice(mini.offset,mini.offset+20).map(h=>`<button class="a-quick-card ${mini.team.includes(h.id)?'chosen':''}" data-a="autoPick" data-id="${esc(h.id)}">${fighter(h,{small:true})}<span>${mini.team.includes(h.id)?'✓ Sélectionné':'Ajouter +'}</span></button>`).join('')}</div><div class="a-pagination">${btn('← Précédent','autoPrev',mini.offset===0?'disabled':'','light')}<span>${mini.offset+1}–${Math.min(pool.length,mini.offset+20)} / ${pool.length}</span>${btn('Suivant →','autoNext',mini.offset+20>=pool.length?'disabled':'','light')}</div>`;}
function miniReplayContents(){const c=registry(mini.worlds,mini.statsMode),e=mini.replay.events[Math.min(Math.max(0,mini.cursor-1),mini.replay.events.length-1)];return `<div class="a-fighters">${e.units.filter(f=>f.team==='B').map((f,i)=>fighter(c.byId.get(mini.enemy[i]),{small:true,combatUnit:f})).join('')}</div><div class="a-versus-divider">VS</div><div class="a-fighters">${e.units.filter(f=>f.team==='A').map((f,i)=>fighter(c.byId.get(mini.team[i]),{small:true,combatUnit:f})).join('')}</div>`;}
