function hpToneOf(pct){return pct>60?'hi':pct>30?'mid':pct>15?'low':'crit';}
function patchBattle(ev){const host=document.querySelector('.a-battle-units');if(!host)return;const c=cat();for(const f of ev.units){let el=host.querySelector('[data-unit="'+CSS.escape(f.uid)+'"]');if(!el)continue;const stats=[f.atk,f.maxHp,f.speed].join('|');if(el.dataset.combatStats!==stats){const tpl=document.createElement('template');tpl.innerHTML=fighter(c.byId.get(f.cardId),{small:true,combatUnit:f});el.replaceWith(tpl.content.firstElementChild);el=host.querySelector('[data-unit="'+CSS.escape(f.uid)+'"]');hydrateCardFaces(el);}const prevHp=Number(el.dataset.hp);const pct=Math.max(0,Math.min(100,f.hp/f.maxHp*100));const tone=hpToneOf(pct);el.classList.toggle('is-ko',!f.alive);el.setAttribute('aria-label',f.name+' · '+Math.round(f.hp)+' PV'+(!f.alive?' · K.O.':''));el.dataset.hp=String(Math.round(f.hp));const barWrap=el.querySelector('.a-card-hp');const bar=el.querySelector('.a-card-hp i');if(barWrap){barWrap.className='a-card-hp is-'+tone;barWrap.dataset.hpPct=String(Math.round(pct));}if(bar)bar.style.width=pct+'%';let heart=el.querySelector('.a-card-hp-heart');if(!heart&&f.alive!==false){heart=document.createElement('span');heart.className='a-card-hp-heart';heart.setAttribute('aria-hidden','true');heart.innerHTML='<b></b>';el.append(heart);}if(heart){heart.className='a-card-hp-heart is-'+tone;const b=heart.querySelector('b');if(b)b.textContent=String(Math.round(f.hp));heart.dataset.hp=String(Math.round(f.hp));}if(Number.isFinite(prevHp)&&f.hp<prevHp){el.classList.remove('is-hurt');barWrap?.classList.remove('is-hurt');heart?.classList.remove('is-hurt');void el.offsetWidth;el.classList.add('is-hurt');barWrap?.classList.add('is-hurt');heart?.classList.add('is-hurt');clearTimeout(el._hurtTimer);el._hurtTimer=setTimeout(()=>{el.classList.remove('is-hurt');barWrap?.classList.remove('is-hurt');heart?.classList.remove('is-hurt');},420);}const hp=el.querySelector('.v193-unit-label small');if(hp)hp.textContent=Math.round(f.hp)+' / '+Math.round(f.maxHp)+' PV';let shield=el.querySelector('.a-shield-badge');if(f.shield>0){if(!shield){shield=document.createElement('span');shield.className='a-shield-badge';el.append(shield);}shield.textContent='⬡ '+Math.round(f.shield);}else shield?.remove();if(f.alive)el.querySelector('.a-ko')?.remove();if(!f.alive&&!el.querySelector('.a-ko')){const ko=document.createElement('span');ko.className='a-ko';ko.textContent='K.O.';el.append(ko);}}paintStates(host,ev);const msg=document.querySelector('.a-event-message');if(msg)msg.textContent=ev.message;const round=document.querySelector('.a-round-token');if(round)round.textContent=ev.round||1;const rail=document.querySelector('.v193-initiative>div');if(rail)rail.innerHTML=initiative(ev);}
function paintBattleEvent(e,previous){clearTimeout(battlePaintTimer);const cursor=run.combat.cursor,delayed=['hit','skill_hit','counter_hit','dot','heal','shield','ko'].includes(e.type)&&!reduced();patchBattle(delayed?{...e,units:previous.units}:e);if(delayed)battlePaintTimer=setTimeout(()=>{if(run?.phase==='combat'&&run.combat.cursor===cursor&&!paused)patchBattle(e);},timing(e,visualContext(e),speed,false).impact);}

function visualContext(e){if(!e)return {};const f=e.units?.find(f=>f.uid===e.actor),source=cat().byId.get(f?.cardId),idx=Number((e.actor||'').split('-')[1]),enemy=e.actor?.startsWith('B'),u=enemy?run.pending?.enemies[idx]:run.units.find(u=>u.uid===run.combat?.played[idx]),weapon=u?gearFor(run,u,enemy).find(g=>g.category==='arme'):null,item=u?gearFor(run,u,enemy).find(g=>e.effect?.startsWith('item:'+g.id)):null;return {technique:source?.effects.find(x=>e.effect===x.key||e.effect?.endsWith(x.key))?.name||item?.name||'',effectType:source?.effects.find(x=>e.effect===x.key||e.effect?.endsWith(x.key))?.type||item?.effect||'',weapon:weapon?.name||'',universe:source?.universe||'DB'};}
